def to_in_store_only(apps, schema_editor):
    """系統只給本店人員使用（使用者 2026-10-16）：車行帳號轉為店內帳號並維持停用，其餘車行專用資料歸位。"""
    Profile = apps.get_model("sales", "OrderAccountProfile")
    AuditLog = apps.get_model("sales", "UserAccountAuditLog")
    User = apps.get_model(settings.AUTH_USER_MODEL)
    for profile in Profile.objects.filter(kind="dealer").select_related("user"):
        user = profile.user
        User.objects.filter(pk=user.pk).update(is_active=False)
        Profile.objects.filter(pk=profile.pk).update(source=None, order_scope="own", identity_epoch=profile.identity_epoch + 1)
        AuditLog.objects.create(target=user, target_username=user.username, action="update",
                                description="移除車行帳號功能：轉為店內帳號並維持停用。")
    Profile.objects.filter(order_scope="dealer").update(order_scope="own")
    # 只給車行看的公告改為「指定人員」且無人可看，不外流給店內或未登入訪客。
    apps.get_model("sales", "SystemAnnouncement").objects.filter(audience__in=["dealer", "dealers"]).update(audience="selected")
    apps.get_model("sales", "SalesOrder").objects.filter(status="intake_pending").update(status="allocation_pending")
    Category = apps.get_model("sales", "SalesSourceCategory")
    if not Category.objects.filter(name="車行").exists():
        Category.objects.filter(name="合作車行", system_behavior="dealer").update(name="車行")


